"use client";

import { Check, Copy } from "lucide-react";
import * as React from "react";

import { SyntaxHighlight } from "@/lib/syntax-highlight";
import { cn } from "@/lib/utils";

type CodeBlockProps = Omit<React.ComponentProps<"div">, "children"> & {
  code: string;
  language?: string;
  filename?: string;
  copyable?: boolean;
  showLineNumbers?: boolean;
};

function CodeBlock({
  code,
  language,
  filename,
  copyable = true,
  showLineNumbers = false,
  className,
  ...props
}: CodeBlockProps) {
  const [copied, setCopied] = React.useState(false);
  const hasHeader = filename !== undefined || language !== undefined || copyable;

  async function copyCode() {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1600);
    } catch {
      setCopied(false);
    }
  }

  return (
    <div
      data-slot="code-block"
      data-language={language}
      className={cn("min-w-0 overflow-hidden border border-border bg-card", className)}
      {...props}
    >
      {hasHeader ? (
        <div
          data-slot="code-block-header"
          className="flex min-h-10 items-stretch border-b border-border bg-muted/20"
        >
          <div className="flex min-w-0 flex-1 items-center gap-3 px-3 font-mono text-[0.625rem] uppercase tracking-[0.14em] text-muted-foreground">
            {filename ? <span className="truncate text-foreground">{filename}</span> : null}
            {language ? <span className="ml-auto shrink-0">{language}</span> : null}
          </div>
          {copyable ? (
            <button
              type="button"
              data-slot="code-block-copy"
              onClick={copyCode}
              className="inline-flex size-10 shrink-0 cursor-pointer items-center justify-center border-l border-border text-muted-foreground outline-none transition-colors duration-100 hover:bg-muted/60 hover:text-foreground focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/40 motion-reduce:transition-none"
              aria-label={copied ? "Code copied" : "Copy code"}
            >
              {copied ? (
                <Check className="size-3.5" aria-hidden="true" />
              ) : (
                <Copy className="size-3.5" aria-hidden="true" />
              )}
              <span className="sr-only" aria-live="polite">
                {copied ? "Code copied to clipboard" : ""}
              </span>
            </button>
          ) : null}
        </div>
      ) : null}

      <pre
        data-slot="code-block-content"
        className={cn(
          "min-w-0 overflow-x-auto py-4 font-mono text-xs leading-6",
          !showLineNumbers && "px-4",
        )}
      >
        <SyntaxHighlight code={code} language={language} showLineNumbers={showLineNumbers} />
      </pre>
    </div>
  );
}

export type { CodeBlockProps };
export { CodeBlock };

import { Highlight, type PrismTheme } from "prism-react-renderer";

const languageAliases: Record<string, string> = {
  html: "markup",
  js: "javascript",
  jsx: "jsx",
  md: "markdown",
  sh: "bash",
  shell: "bash",
  ts: "typescript",
  tsx: "tsx",
  xml: "markup",
  yml: "yaml",
};

const rivetSyntaxTheme: PrismTheme = {
  plain: {
    color: "var(--foreground)",
  },
  styles: [
    {
      types: ["comment", "prolog", "doctype", "cdata"],
      style: {
        color: "var(--muted-foreground)",
        fontStyle: "italic",
      },
    },
    {
      types: ["punctuation", "operator", "entity", "url"],
      style: {
        color: "color-mix(in oklab, var(--muted-foreground) 84%, transparent)",
      },
    },
    {
      types: ["string", "char", "attr-value", "regex", "inserted"],
      style: {
        color: "color-mix(in oklab, var(--foreground) 72%, var(--muted-foreground))",
      },
    },
    {
      types: ["keyword", "module", "control-flow", "important", "atrule"],
      style: {
        color: "var(--foreground)",
        fontWeight: "600",
      },
    },
    {
      types: [
        "function",
        "function-variable",
        "class-name",
        "builtin",
        "property",
        "tag",
        "attr-name",
      ],
      style: {
        color: "color-mix(in oklab, var(--foreground) 88%, var(--muted-foreground))",
        fontWeight: "600",
      },
    },
    {
      types: ["boolean", "number", "constant", "symbol", "variable"],
      style: {
        color: "color-mix(in oklab, var(--foreground) 80%, var(--muted-foreground))",
      },
    },
    {
      types: ["deleted"],
      style: {
        color: "var(--destructive)",
      },
    },
  ],
};

type SyntaxHighlightProps = {
  code: string;
  language?: string;
  showLineNumbers?: boolean;
};

function normalizeLanguage(language: string | undefined) {
  const normalizedLanguage = language?.trim().toLowerCase() || "text";

  return languageAliases[normalizedLanguage] ?? normalizedLanguage;
}

function getLineIds(code: string) {
  const occurrences = new Map<string, number>();

  return code.split("\n").map((content) => {
    const occurrence = (occurrences.get(content) ?? 0) + 1;
    occurrences.set(content, occurrence);

    return `${content}-${occurrence}`;
  });
}

function SyntaxHighlight({ code, language, showLineNumbers = false }: SyntaxHighlightProps) {
  const normalizedLanguage = normalizeLanguage(language);
  const lineIds = getLineIds(code);

  return (
    <Highlight code={code} language={normalizedLanguage} theme={rivetSyntaxTheme}>
      {({ tokens, getLineProps, getTokenProps }) => (
        <code data-language={language} className={`language-${normalizedLanguage}`}>
          {tokens.map((line, lineIndex) => {
            const lineProps = getLineProps({ line });
            const tokenOccurrences = new Map<string, number>();
            const content = line.map((token) => {
              const tokenProps = getTokenProps({ token });
              const signature = `${token.types.join(":")}-${token.content}`;
              const occurrence = (tokenOccurrences.get(signature) ?? 0) + 1;
              tokenOccurrences.set(signature, occurrence);

              return <span {...tokenProps} key={`${signature}-${occurrence}`} />;
            });

            if (showLineNumbers) {
              return (
                <span
                  {...lineProps}
                  key={lineIds[lineIndex]}
                  className={`${lineProps.className} table w-full min-w-max table-fixed`}
                >
                  <span
                    key="line-number"
                    aria-hidden="true"
                    className="table-cell w-12 select-none border-r border-border pr-3 text-right tabular-nums text-muted-foreground/60"
                  >
                    {lineIndex + 1}
                  </span>
                  <span key="line-content" className="table-cell px-4 whitespace-pre">
                    {content}
                  </span>
                </span>
              );
            }

            return (
              <span {...lineProps} key={lineIds[lineIndex]}>
                {content}
                {lineIndex < tokens.length - 1 ? "\n" : null}
              </span>
            );
          })}
        </code>
      )}
    </Highlight>
  );
}

export type { SyntaxHighlightProps };
export { SyntaxHighlight };
